const ELEMENT_PROP_KEYS = new Set(["theme","prefix","suffix","count","stagger","flight","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  prefix: "Live in",
  suffix: "countries",
  count: 142,
  stagger: 20,
  flight: 32,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type DotGlobeElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof DotGlobeBase>;

const DotGlobeInner = forwardRef<
  HTMLDivElement,
  DotGlobeElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<DotGlobe>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <DotGlobeBase
          {...(componentProps as unknown as ComponentProps<typeof DotGlobeBase>)}
        />
      </div>
    </Sequence>
  );
});

export const DotGlobe = Interactive.withSchema({
  Component: DotGlobeInner,
  componentName: "<DotGlobe>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
